trial.program_source:
def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid);w=len(grid[0])
    hm={2:8,8:2,7:4,4:7}
    vm={2:7,7:2,8:4,4:8}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in hm:
                out[r][w-1-c]=hm[v]
                out[h-1-r][c]=vm[v]
                out[h-1-r][w-1-c]=vm[hm[v]]
    return out

